public class Solution{long F(long[]a,long[]t,int l,int r,long lo,long hi){if(r-l<=1)return 0;int m=(l+r)/2;long c=F(a,t,l,m,lo,hi)+F(a,t,m,r,lo,hi);int p=m,q=m;for(int i=l;i<m;i++){while(p<r&&a[p]-a[i]<lo)p++;while(q<r&&a[q]-a[i]<=hi)q++;c+=q-p;}int x=l,y=m,k=l;while(x<m||y<r)t[k++]=(y==r||(x<m&&a[x]<=a[y]))?a[x++]:a[y++];for(int i=l;i<r;i++)a[i]=t[i];return c;}public int CountRangeSum(int[]nums,int lower,int upper){long[]a=new long[nums.Length+1],t=new long[nums.Length+1];for(int i=0;i<nums.Length;i++)a[i+1]=a[i]+nums[i];return(int)F(a,t,0,a.Length,lower,upper);}}
